package localchat;
import javax.swing.*;
import java.awt.*;
import java.awt.datatransfer.*;
import java.awt.event.*;
import java.nio.file.*;
import java.util.*;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

/** Draft editing via real key events and clipboard, plus per-chat reset and failure boundaries. */
public final class ComposerShortcutsTest {
    static int checks;static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
    static void action(JTextArea input,int key,int modifiers){Object id=input.getInputMap().get(KeyStroke.getKeyStroke(key,modifiers));Action action=input.getActionMap().get(id);check(action!=null,"shortcut action present");if(action.isEnabled())action.actionPerformed(new ActionEvent(input,0,"shortcut"));}
    /** Real typing is only meaningful once the editor really owns keyboard focus; re-click (bounded) until it does, so a slow window activation cannot make the first keystrokes vanish. */
    static void ensureEditorFocus(Robot robot,LocalChat app)throws Exception{for(int attempt=0;attempt<5;attempt++){boolean[] focused={false};FeatureTest.edt(()->focused[0]=KeyboardFocusManager.getCurrentKeyboardFocusManager().getFocusOwner()==AttachmentTest.input(app));if(focused[0])return;Point[] at={null};FeatureTest.edt(()->{app.toFront();at[0]=AttachmentTest.input(app).getLocationOnScreen();at[0].translate(35,25);});robot.mouseMove(at[0].x,at[0].y);robot.mousePress(InputEvent.BUTTON1_DOWN_MASK);robot.mouseRelease(InputEvent.BUTTON1_DOWN_MASK);robot.waitForIdle();Thread.sleep(300);}throw new AssertionError("native editor never received keyboard focus; another window is in front");}
    static void chord(Robot robot,int key,boolean shift){robot.keyPress(KeyEvent.VK_CONTROL);if(shift)robot.keyPress(KeyEvent.VK_SHIFT);robot.keyPress(key);robot.keyRelease(key);if(shift)robot.keyRelease(KeyEvent.VK_SHIFT);robot.keyRelease(KeyEvent.VK_CONTROL);robot.delay(150);robot.waitForIdle();}
    static String value(LocalChat app)throws Exception{String[] result={null};FeatureTest.edt(()->result[0]=AttachmentTest.input(app).getText());return result[0];}
    static void fixtures(Path home,String url)throws Exception{FeatureTest.edt(()->{
        LocalChat app=AttachmentTest.window(home,url);JTextArea input=AttachmentTest.input(app);Clipboard clip=new Clipboard("isolated shortcut test");AtomicInteger errors=new AtomicInteger();ComposerClipboard.install(input,()->clip,e->errors.incrementAndGet());
        for(int language=0;language<6;language++)for(int theme=0;theme<2;theme++){
            ((JComboBox<?>)FeatureTest.field(app,"languageBox")).setSelectedIndex(language);((JComboBox<?>)FeatureTest.field(app,"themeBox")).setSelectedIndex(theme);
            ComposerEditing.setText(input,"before SELECT after");input.select(7,13);clip.setContents(new StringSelection("linie 1\nRomana 日本語"),null);action(input,KeyEvent.VK_V,InputEvent.CTRL_DOWN_MASK);check(input.getText().equals("before linie 1\nRomana 日本語 after"),"paste replaces selected text exactly");
            action(input,KeyEvent.VK_Z,InputEvent.CTRL_DOWN_MASK);check(input.getText().equals("before SELECT after"),"one Undo restores entire replaced selection");action(input,KeyEvent.VK_Y,InputEvent.CTRL_DOWN_MASK);check(input.getText().contains("日本語"),"Redo restores paste");action(input,KeyEvent.VK_Z,InputEvent.CTRL_DOWN_MASK);action(input,KeyEvent.VK_Z,InputEvent.CTRL_DOWN_MASK|InputEvent.SHIFT_DOWN_MASK);check(input.getText().contains("日本語"),"Ctrl+Shift+Z restores paste");
            action(input,KeyEvent.VK_A,InputEvent.CTRL_DOWN_MASK);action(input,KeyEvent.VK_C,InputEvent.CTRL_DOWN_MASK);String copied=(String)clip.getData(DataFlavor.stringFlavor);check(copied.equals(input.getText()),"Ctrl+A/C copy original multiline Unicode");action(input,KeyEvent.VK_X,InputEvent.CTRL_DOWN_MASK);check(input.getText().isEmpty()&&clip.getData(DataFlavor.stringFlavor).equals(copied),"Ctrl+X removes only after successful copy");action(input,KeyEvent.VK_Z,InputEvent.CTRL_DOWN_MASK);check(input.getText().equals(copied),"Undo restores cut text");
            var menu=input.getComponentPopupMenu();for(var listener:menu.getPopupMenuListeners())listener.popupMenuWillBecomeVisible(new javax.swing.event.PopupMenuEvent(menu));check(((JMenuItem)menu.getComponent(6)).getText().equals(I18n.text("Anuleaza editarea"))&&((JMenuItem)menu.getComponent(7)).getText().equals(I18n.text("Refa editarea")),"translated Undo/Redo menu survives theme changes");
        }
        ComposerEditing.setText(input,"draft A");input.append(" edited");FeatureTest.call(app,"ensureSession",new Class<?>[]{});FeatureTest.call(app,"saveConversation",new Class<?>[]{});Path first=FeatureTest.field(app,"conversationFile");
        FeatureTest.command(app,"/new Other");action(input,KeyEvent.VK_Z,InputEvent.CTRL_DOWN_MASK);check(input.getText().isEmpty(),"Undo cannot resurrect draft from previous chat");input.append("draft B");FeatureTest.call(app,"openSession",new Class<?>[]{Conversations.Saved.class},Conversations.load(first));action(input,KeyEvent.VK_Z,InputEvent.CTRL_DOWN_MASK);check(input.getText().equals("draft A edited"),"resumed draft has isolated editing boundary");input.append(" more");action(input,KeyEvent.VK_Z,InputEvent.CTRL_DOWN_MASK);check(input.getText().equals("draft A edited"),"Undo works after resuming a saved conversation");
        Clipboard locked=new Clipboard("locked write"){public synchronized void setContents(Transferable data,ClipboardOwner owner){throw new IllegalStateException("fixture locked");}};ComposerClipboard.install(input,()->locked,e->errors.incrementAndGet());input.selectAll();int prior=errors.get();action(input,KeyEvent.VK_X,InputEvent.CTRL_DOWN_MASK);check(errors.get()==prior+1&&input.getText().equals("draft A edited"),"permanent clipboard lock preserves cut selection and draft");
        AtomicInteger attempts=new AtomicInteger();Clipboard transientClip=new Clipboard("temporary write lock"){public synchronized void setContents(Transferable data,ClipboardOwner owner){if(attempts.incrementAndGet()<3)throw new IllegalStateException("fixture lock");super.setContents(data,owner);}};ComposerClipboard.store(transientClip,new StringSelection("recovered"));check(attempts.get()==3&&transientClip.getData(DataFlavor.stringFlavor).equals("recovered"),"clipboard write retries without text duplication");app.dispose();
    });}
    static void nativeKeys(Path home,String url)throws Exception{
        LocalChat[] app={null};Point[] target={null};FeatureTest.edt(()->{app[0]=AttachmentTest.window(home,url);app[0].setLocation(40,40);app[0].setAlwaysOnTop(true);app[0].setVisible(true);app[0].toFront();app[0].validate();JTextArea input=AttachmentTest.input(app[0]);ComposerEditing.setText(input,"");target[0]=input.getLocationOnScreen();target[0].translate(35,25);});
        Robot robot=new Robot();robot.setAutoDelay(60);robot.setAutoWaitForIdle(true);robot.mouseRelease(java.awt.event.InputEvent.BUTTON1_DOWN_MASK|java.awt.event.InputEvent.BUTTON2_DOWN_MASK|java.awt.event.InputEvent.BUTTON3_DOWN_MASK);for(int key:new int[]{java.awt.event.KeyEvent.VK_CONTROL,java.awt.event.KeyEvent.VK_SHIFT,java.awt.event.KeyEvent.VK_ALT})robot.keyRelease(key);Thread.sleep(700);FeatureTest.edt(()->{target[0]=AttachmentTest.input(app[0]).getLocationOnScreen();target[0].translate(35,25);});robot.mouseMove(target[0].x,target[0].y);robot.mousePress(InputEvent.BUTTON1_DOWN_MASK);robot.mouseRelease(InputEvent.BUTTON1_DOWN_MASK);robot.waitForIdle();
        ensureEditorFocus(robot,app[0]);for(int key:new int[]{KeyEvent.VK_A,KeyEvent.VK_B,KeyEvent.VK_C}){robot.keyPress(key);robot.keyRelease(key);}robot.waitForIdle();check(value(app[0]).equals("abc"),"real keyboard typing reaches prompt");
        Clipboard clip=Toolkit.getDefaultToolkit().getSystemClipboard();chord(robot,KeyEvent.VK_A,false);chord(robot,KeyEvent.VK_C,false);check(ComposerClipboard.contents(clip).getTransferData(DataFlavor.stringFlavor).equals("abc"),"native Ctrl+A/C copy to Windows clipboard");
        chord(robot,KeyEvent.VK_X,false);check(value(app[0]).isEmpty(),"native Ctrl+X cuts selection");chord(robot,KeyEvent.VK_V,false);check(value(app[0]).equals("abc"),"native Ctrl+V pastes from Windows clipboard");chord(robot,KeyEvent.VK_Z,false);check(value(app[0]).isEmpty(),"native Ctrl+Z undoes paste");chord(robot,KeyEvent.VK_Y,false);check(value(app[0]).equals("abc"),"native Ctrl+Y redoes paste");chord(robot,KeyEvent.VK_Z,false);chord(robot,KeyEvent.VK_Z,true);check(value(app[0]).equals("abc"),"native Ctrl+Shift+Z redoes paste");
        for(int theme=0;theme<2;theme++){final int selection=theme;FeatureTest.edt(()->{((JComboBox<?>)FeatureTest.field(app[0],"themeBox")).setSelectedIndex(selection);AttachmentTest.input(app[0]).requestFocusInWindow();app[0].validate();});robot.waitForIdle();Thread.sleep(300);FeatureTest.edt(()->{target[0]=AttachmentTest.input(app[0]).getLocationOnScreen();target[0].translate(35,25);});robot.mouseMove(target[0].x,target[0].y);robot.mousePress(InputEvent.BUTTON1_DOWN_MASK);robot.mouseRelease(InputEvent.BUTTON1_DOWN_MASK);robot.waitForIdle();FeatureTest.edt(()->check(KeyboardFocusManager.getCurrentKeyboardFocusManager().getFocusOwner()==AttachmentTest.input(app[0]),"native editor focus settled after theme change"));chord(robot,KeyEvent.VK_A,false);chord(robot,KeyEvent.VK_C,false);check(ComposerClipboard.contents(clip).getTransferData(DataFlavor.stringFlavor).equals("abc"),"native copy survives theme change");ComposerClipboard.store(clip,new StringSelection("replacement"));chord(robot,KeyEvent.VK_V,false);check(value(app[0]).equals("replacement"),"native paste replaces selection after theme change");chord(robot,KeyEvent.VK_Z,false);check(value(app[0]).equals("abc"),"native Undo restores selection in one step after theme change");}
        FeatureTest.edt(()->app[0].dispose());
    }
    public static void main(String[] args)throws Exception{
        Path home=Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("localchat.home"))),"run-");System.out.println("Shortcut QA: "+home);Clipboard clip=Boolean.getBoolean("localchat.skipNativeQA")?new Clipboard("isolated non-native QA"):Toolkit.getDefaultToolkit().getSystemClipboard();Transferable current=ComposerClipboard.contents(clip);Map<DataFlavor,Object> saved=new LinkedHashMap<>();if(current!=null)for(DataFlavor flavor:current.getTransferDataFlavors())try{saved.put(flavor,current.getTransferData(flavor));}catch(Exception ignored){}
        try(var server=new FeatureTest.Server(FeatureTest.sse("data: [DONE]\n\n"))){fixtures(Files.createDirectories(home.resolve("fixtures")),server.url());if(!Boolean.getBoolean("localchat.skipNativeQA"))nativeKeys(Files.createDirectories(home.resolve("native")),server.url());else System.out.println("Native keyboard/Windows clipboard checks explicitly skipped; deterministic shortcut fixtures still ran");check(server.requests.isEmpty(),"editing, clipboard, themes and chat reload never call the model");System.out.println("PASS: "+checks+" composer shortcut checks; Undo/Redo, six languages and chat isolation; native="+!Boolean.getBoolean("localchat.skipNativeQA"));}
        finally{FeatureTest.edt(()->{for(var window:Window.getWindows())window.dispose();});if(!saved.isEmpty())ComposerClipboard.store(clip,new Transferable(){public DataFlavor[] getTransferDataFlavors(){return saved.keySet().toArray(DataFlavor[]::new);}public boolean isDataFlavorSupported(DataFlavor f){return saved.containsKey(f);}public Object getTransferData(DataFlavor f)throws UnsupportedFlavorException{if(!saved.containsKey(f))throw new UnsupportedFlavorException(f);return saved.get(f);}});}System.exit(0);
    }
}
